"""Order value and ledger reconciliation. Pure functions, no database access.

Money is integer cents; weights are Decimal kilograms (NUMERIC(14,3) in the DB).
All arithmetic is done in Decimal and rounded half-up to whole cents once.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import Iterable

RECEIVABLE_ACCOUNT = "1200-AR"
KG_QUANTUM = Decimal("0.001")

# Orders in these statuses are not billed.
UNBILLED_STATUSES = frozenset({"cancelled", "rejected"})


@dataclass(frozen=True)
class Mismatch:
    order_no: str
    expected_cents: int
    booked_cents: int

    @property
    def diff_cents(self) -> int:
        return self.booked_cents - self.expected_cents


def accepted_weight_kg(order) -> Decimal:
    """Weight the buyer is billed for: net weight, or zero if the order is not billed."""
    if order.status in UNBILLED_STATUSES:
        return Decimal("0.000")
    return Decimal(order.net_weight_kg).quantize(KG_QUANTUM, rounding=ROUND_HALF_UP)


def order_value_cents(order) -> int:
    """accepted weight x price per kg, rounded half-up to whole cents."""
    value = accepted_weight_kg(order) * Decimal(order.price_per_kg_cents)
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def reconcile(orders: Iterable, ledger_entries: Iterable) -> list[Mismatch]:
    """Compare each order's value with the posted receivable entries booked for it.

    Pending entries are ignored. Reversing entries (negative amounts) count,
    so a correction that nets out is not a mismatch.
    """
    booked: dict[int, int] = {}
    for entry in ledger_entries:
        if entry.account_code != RECEIVABLE_ACCOUNT or entry.status != "posted":
            continue
        if entry.order_id is None:
            continue
        booked[entry.order_id] = booked.get(entry.order_id, 0) + int(entry.amount_cents)

    mismatches: list[Mismatch] = []
    for order in sorted(orders, key=lambda o: o.order_no):
        expected = order_value_cents(order)
        actual = booked.get(order.id, 0)
        if expected != actual:
            mismatches.append(Mismatch(order.order_no, expected, actual))
    return mismatches
"""legacy-sync: nightly two-way sync between Acme's old ERP and the orders DB.

README: run `python sync.py --direction pull|push` from cron. Owned by
@acme/integrations. Table and column names come from ERP_FIELD_MAP and the
ERP export config at runtime, so static analysis cannot see which tables or
columns this script touches. Treat every schema change on orders,
order_import_staging or their columns as possibly affecting this script.
"""

import argparse
import os

import psycopg

# ERP field name -> orders column. Extended by ops via ERP_EXTRA_FIELDS.
ERP_FIELD_MAP = {
    "ORDNR": "order_no",
    "WGT_NET": "net_weight_kg",
    "PRC_KG": "price_per_kg_cents",
    "STAT": "status",
}

# Tables the ERP export may read from, picked per run by the ERP config.
SOURCE_TABLES = os.environ.get("ERP_SOURCE_TABLES", "orders,order_import_staging").split(",")


def field_map() -> dict[str, str]:
    extra = os.environ.get("ERP_EXTRA_FIELDS", "")
    mapping = dict(ERP_FIELD_MAP)
    for pair in filter(None, extra.split(",")):
        erp_name, column = pair.split("=", 1)
        mapping[erp_name.strip()] = column.strip()
    return mapping


def push_weights(conn: psycopg.Connection, table: str) -> list[tuple]:
    """Read order weights to send to the ERP."""
    with conn.cursor() as cur:
        if table == "order_import_staging":
            cur.execute(
                f"SELECT raw->>'ref' AS order_no, (raw->>'weight_t')::numeric * 1000 FROM {table}"
            )
        else:
            cur.execute(f"SELECT order_no, net_weight_kg FROM {table}")
        return cur.fetchall()


def pull_updates(conn: psycopg.Connection, erp_rows: list[dict]) -> int:
    """Apply ERP-side edits to orders, one field at a time."""
    mapping = field_map()
    updated = 0
    with conn.cursor() as cur:
        for row in erp_rows:
            order_no = row["ORDNR"]
            for erp_name, value in row.items():
                field = mapping.get(erp_name)
                if field is None or field == "order_no":
                    continue
                cur.execute(f"UPDATE orders SET {field} = %s WHERE order_no = %s", (value, order_no))
                updated += cur.rowcount
    conn.commit()
    return updated


def read_erp_export(path: str) -> list[dict]:
    rows = []
    with open(path, encoding="latin-1") as fh:
        header = fh.readline().rstrip("\n").split(";")
        for line in fh:
            rows.append(dict(zip(header, line.rstrip("\n").split(";"))))

